const rows = 4;
const cols = 4;
const start = { row: 0, col: 0 };
const goal = { row: 3, col: 3 };
const obstacles = [{ row: 1, col: 1 }, { row: 1, col: 2 }];

// Movement order: Right, Down, Left, Up (no diagonals), step cost 1
const moves = [
  { name: 'Right', dr: 0, dc: 1 },
  { name: 'Down', dr: 1, dc: 0 },
  { name: 'Left', dr: 0, dc: -1 },
  { name: 'Up', dr: -1, dc: 0 },
];
const stepCost = 1;

const grid = [];
for (let r = 0; r < rows; r++) {
  const line = [];
  for (let c = 0; c < cols; c++) {
    const isObstacle = obstacles.some(function (o) { return o.row === r && o.col === c; });
    line.push(isObstacle ? 1 : 0);
  }
  grid.push(line);
}

return [{ json: { rows, cols, start, goal, obstacles, moves, stepCost, grid } }];

const d = $input.first().json;
const errors = [];

function inside(p) {
  return Number.isInteger(p.row) && Number.isInteger(p.col) &&
    p.row >= 0 && p.row < d.rows && p.col >= 0 && p.col < d.cols;
}
function isObstacle(p) {
  return d.obstacles.some(function (o) { return o.row === p.row && o.col === p.col; });
}

if (!inside(d.start)) errors.push('Start is outside the grid');
if (!inside(d.goal)) errors.push('Goal is outside the grid');
d.obstacles.forEach(function (o) {
  if (!inside(o)) errors.push('Obstacle (' + o.row + ',' + o.col + ') is outside the grid');
});
if (isObstacle(d.start)) errors.push('Start is on an obstacle');
if (isObstacle(d.goal)) errors.push('Goal is on an obstacle');

const validation = errors.length === 0 ? 'passed' : 'failed';
return [{ json: Object.assign({}, d, { validation: validation, validationErrors: errors }) }];

const d = $input.first().json;

if (d.validation !== 'passed') {
  return [{ json: Object.assign({}, d, {
    pathFound: false,
    expandedNodes: [],
    path: [],
    message: 'Validation failed: ' + d.validationErrors.join('; '),
  }) }];
}

const key = function (r, c) { return r + ',' + c; };
const blocked = {};
d.obstacles.forEach(function (o) { blocked[key(o.row, o.col)] = true; });

const queue = [{ row: d.start.row, col: d.start.col }]; // FIFO: push to back, shift from front
const visited = {};
visited[key(d.start.row, d.start.col)] = true; // mark visited when enqueued
const parent = {};
parent[key(d.start.row, d.start.col)] = null;
const expandedNodes = [];
let reached = false;

while (queue.length > 0) {
  const cur = queue.shift();
  expandedNodes.push([cur.row, cur.col]); // expanded when removed from queue
  if (cur.row === d.goal.row && cur.col === d.goal.col) {
    reached = true;
    break;
  }
  for (let i = 0; i < d.moves.length; i++) {
    const m = d.moves[i];
    const nr = cur.row + m.dr;
    const nc = cur.col + m.dc;
    if (nr < 0 || nr >= d.rows || nc < 0 || nc >= d.cols) continue; // out of grid
    if (blocked[key(nr, nc)]) continue; // obstacle
    if (visited[key(nr, nc)]) continue; // already visited
    visited[key(nr, nc)] = true;
    parent[key(nr, nc)] = { row: cur.row, col: cur.col };
    queue.push({ row: nr, col: nc });
  }
}

let path = [];
if (reached) {
  let node = { row: d.goal.row, col: d.goal.col };
  while (node) {
    path.push([node.row, node.col]);
    node = parent[key(node.row, node.col)];
  }
  path.reverse();
}

return [{ json: Object.assign({}, d, {
  pathFound: reached,
  expandedNodes: expandedNodes,
  path: path,
  message: reached ? 'Goal reached' : 'Goal is unreachable',
}) }];

const d = $input.first().json;
const path = d.path;
const totalCost = (path.length - 1) * d.stepCost;

function isObstacle(r, c) {
  return d.obstacles.some(function (o) { return o.row === r && o.col === c; });
}

const startsAtStart = path[0][0] === d.start.row && path[0][1] === d.start.col;
const endsAtGoal = path[path.length - 1][0] === d.goal.row && path[path.length - 1][1] === d.goal.col;
let avoidsObstacles = true;
let oneStepMoves = true;
for (let i = 0; i < path.length; i++) {
  if (isObstacle(path[i][0], path[i][1])) avoidsObstacles = false;
  if (i > 0) {
    const dist = Math.abs(path[i][0] - path[i - 1][0]) + Math.abs(path[i][1] - path[i - 1][1]);
    if (dist !== 1) oneStepMoves = false;
  }
}
const pathCheck = {
  startsAtStart: startsAtStart,
  endsAtGoal: endsAtGoal,
  avoidsObstacles: avoidsObstacles,
  movesOneStepAtATime: oneStepMoves,
  allPassed: startsAtStart && endsAtGoal && avoidsObstacles && oneStepMoves,
};

// Emoji grid
const onPath = {};
path.forEach(function (p) { onPath[p[0] + ',' + p[1]] = true; });
const lines = [];
for (let r = 0; r < d.rows; r++) {
  let line = '';
  for (let c = 0; c < d.cols; c++) {
    if (r === d.start.row && c === d.start.col) line += '🤖';
    else if (r === d.goal.row && c === d.goal.col) line += '🏁';
    else if (isObstacle(r, c)) line += '⬛';
    else if (onPath[r + ',' + c]) line += '🟩';
    else line += '⬜';
  }
  lines.push(line);
}

function fmt(list) {
  return list.map(function (p) { return '(' + p[0] + ',' + p[1] + ')'; }).join(' -> ');
}

return [{ json: {
  branch: 'Path found',
  validation: d.validation,
  expandedNodes: d.expandedNodes,
  expandedNodesText: fmt(d.expandedNodes),
  finalPath: path,
  finalPathText: fmt(path),
  totalCost: totalCost,
  pathCheck: pathCheck,
  visualGrid: lines.join('\n'),
  visualGridRows: lines,
} }];
